mapper.update:
UPDATE t_link
SET total_pv  = total_pv + #{totalPv},
    total_uv  = total_uv + #{totalUv},
    total_uip = total_uip + #{totalUip}
WHERE gid = #{gid}
  AND full_short_url = #{fullShortUrl}

mapper.select:
SELECT tl.*, COALESCE(tlst.today_pv, 0) as pv, COALESCE(tlst.today_uv, 0) as uv, COALESCE(tlst.today_uip, 0) as uip FROM t_link tl LEFT JOIN t_link_stats_today tlst ON tl.full_short_url = tlst.full_short_url AND tlst.date = CURDATE() WHERE tl.gid IN
#{item}
AND tl.enable_status = '1' AND tl.del_flag = '0' AND tl.del_time = 0 ORDER BY tl.update_time
